python - <<'PY'
import re
text=open('deliverables/plan.md',encoding='utf-8').read()
# table consistency
lines=text.splitlines(); blocks=[]; cur=[]
for i,l in enumerate(lines,1):
    if l.strip().startswith('|'): cur.append((i,l))
    else:
        if cur: blocks.append(cur); cur=[]
if cur: blocks.append(cur)
bad=0
for b in blocks:
    counts={len(l.strip().strip('|').split('|')) for _,l in b}
    if len(counts)>1:
        bad+=1; print('BAD',b[0][0],counts)
print('tables',len(blocks),'bad',bad)
# budget sum
start=text.index('| Line | Calculation | Cost |'); end=text.index('| Summary |')
total=0; subs=[]
for line in text[start:end].splitlines():
    if not line.startswith('|'): continue
    cells=[c.strip() for c in line.strip('|').split('|')]
    if len(cells)!=3: continue
    n,c,v=cells
    if n.startswith('**Subtotal'):
        subs.append(int(re.search(r'£([\d,]+)',v).group(1).replace(',','')))
    elif n.startswith('**') and n.endswith('**'):
        pass
    elif n not in ('Line','---') and not set(n)<=set('-: '):
        m=re.search(r'£([\d,]+)',v)
        if m: total+=int(m.group(1).replace(',',''))
print('direct',total,'subtotals',sum(subs),len(subs),'total',total+5372,'headroom',60000-(total+5372))
print('words',len(text.split()))
